<script setup lang="ts">
import {onMounted,ref} from "vue";
import {apiGet,apiPatch,apiPost,getApiErrorMessage} from "../lib/api";
import {useSessionStore} from "../stores/session";
import {useToastStore} from "../stores/toasts";
interface OtStatus{id:number;name:string;color:string;sort_order:number;active:boolean;is_initial:boolean;is_final:boolean;marks_quoted:boolean;marks_awaiting_quote_approval:boolean;marks_repair:boolean;marks_waiting_parts:boolean;marks_completed:boolean;notify_whatsapp:boolean;notify_email:boolean;notifications_active:boolean;notification_template:string|null;notification_email_subject:string|null;marks_delivered:boolean}
const session=useSessionStore(),toast=useToastStore(),statuses=ref<OtStatus[]>([]),loading=ref(false),showNew=ref(false);
const fresh=()=>({name:"",color:"#3B82F6",sort_order:90,active:true,is_initial:false,is_final:false,marks_quoted:false,marks_awaiting_quote_approval:false,marks_repair:false,marks_waiting_parts:false,marks_completed:false,notify_whatsapp:false,notify_email:false,notifications_active:true,notification_template:null,notification_email_subject:null,marks_delivered:false});const newStatus=ref(fresh());
async function load(){loading.value=true;try{statuses.value=await apiGet<OtStatus[]>("/work-orders/statuses")}catch(e){toast.push(getApiErrorMessage(e),"error")}finally{loading.value=false}}
async function save(st:OtStatus){try{await apiPatch("/work-orders/statuses/"+st.id,st);await load();toast.push("Estado guardado","success")}catch(e){toast.push(getApiErrorMessage(e),"error")}}
async function create(){try{await apiPost("/work-orders/statuses",newStatus.value);showNew.value=false;newStatus.value=fresh();await load();toast.push("Estado creado","success")}catch(e){toast.push(getApiErrorMessage(e),"error")}}
const templateVariables=ref<string[]>([]);async function loadVariables(){try{const r=await apiGet<{variables:string[]}>("/work-orders/notifications/variables");templateVariables.value=r.variables}catch(_){templateVariables.value=["cliente","numero_ot","equipo","estado"]}}onMounted(async()=>{await load();await loadVariables()});
</script>
<template><div class="card"><div class="flex flex--between heading"><div><h2>Estados de órdenes de trabajo</h2><p class="text-secondary">Flujo propio de {{session.activeCompany?.name}}. El color de cada estado identifica también las filas de las OT.</p></div><button class="btn btn--primary desktop-primary-action" @click="showNew=true">+ Nuevo estado</button><button class="mobile-fab" aria-label="Nuevo estado" @click="showNew=true">+<span>Estado</span></button></div><div v-if="loading" class="text-muted">Cargando estados…</div><div v-else class="status-admin"><div v-for="st in statuses" :key="st.id" class="row" :style="{'--status-color':st.color,background:st.color+'16',borderColor:st.color+'55'}"><input v-model="st.color" class="color" type="color"><div class="field name"><label>Nombre</label><input v-model="st.name"></div><div class="field order"><label>Orden</label><input v-model.number="st.sort_order" type="number" min="0"></div><label class="check"><input v-model="st.active" type="checkbox"> Activo</label><label class="check"><input v-model="st.is_initial" type="checkbox"> Inicial</label><label class="check"><input v-model="st.is_final" type="checkbox"> Final (bloquea OT)</label><label class="check"><input v-model="st.marks_quoted" type="checkbox"> Presupuesto generado</label><label class="check"><input v-model="st.marks_awaiting_quote_approval" type="checkbox"> Espera aprobación</label><label class="check"><input v-model="st.marks_repair" type="checkbox"> En reparación</label><label class="check"><input v-model="st.marks_waiting_parts" type="checkbox"> Espera repuesto</label><label class="check"><input v-model="st.marks_completed" type="checkbox"> Finaliza trabajo</label><label class="check"><input v-model="st.marks_delivered" type="checkbox"> Entrega equipo</label><button class="btn btn--ghost btn--sm" @click="save(st)">Guardar</button><div class="notif-config"><label class="check"><input v-model="st.notifications_active" type="checkbox"> Avisos al cliente</label><label class="check"><input v-model="st.notify_whatsapp" type="checkbox" :disabled="!st.notifications_active"> WhatsApp</label><label class="check"><input v-model="st.notify_email" type="checkbox" :disabled="!st.notifications_active"> Email</label><div class="field notif-template"><label>Mensaje</label><textarea v-model="st.notification_template" rows="2" :disabled="!st.notifications_active" placeholder="Hola {{cliente}}, tu OT N° {{numero_ot}} pasó a {{estado}}."></textarea></div><div class="field notif-template"><label>Asunto del email</label><input v-model="st.notification_email_subject" :disabled="!st.notifications_active || !st.notify_email" placeholder="Tu orden de trabajo {{numero_ot}}"></div><p v-if="st.notifications_active && (st.notify_whatsapp || st.notify_email)" class="notif-hint">Variables: {{ templateVariables.join(", ") }}</p></div></div></div><p class="text-muted note">“Presupuesto generado” identifica el estado al que pasa automáticamente la OT al emitir un presupuesto. “Finaliza trabajo” registra la finalización técnica. “Entrega equipo” registra la entrega real al cliente. <strong>“Espera repuesto”</strong> marca las OT frenadas por un repuesto: es lo que cuenta el panel “Requieren atención”, así que el nombre del estado puede ser el que quieras. Un mismo flag puede estar activo en un solo estado: al activarlo en uno nuevo se desactiva en el anterior. <strong>“Ciclo finalizado”</strong> marca un estado como <strong>final</strong>: cuando la OT llega a él, el ciclo se cierra y no se puede cambiar de estado, ni generar diagnóstico, presupuesto, enviarlo, decidirlo, reabrir el diagnóstico ni modificar la fecha de entrega prevista.</p></div><div v-if="showNew" class="modal-backdrop"><div class="modal card status-modal"><div class="flex flex--between"><h2>Nuevo estado de OT</h2><button class="btn btn--ghost" @click="showNew=false">×</button></div><div class="field"><label>Nombre *</label><input v-model="newStatus.name" autofocus></div><div class="field__row"><div class="field"><label>Color</label><input v-model="newStatus.color" class="color color--large" type="color"></div><div class="field"><label>Orden</label><input v-model.number="newStatus.sort_order" type="number" min="0"></div></div><div class="flags"><label class="check"><input v-model="newStatus.active" type="checkbox"> Activo</label><label class="check"><input v-model="newStatus.is_initial" type="checkbox"> Estado inicial</label><label class="check"><input v-model="newStatus.is_final" type="checkbox"> Ciclo finalizado (bloquea OT)</label><label class="check"><input v-model="newStatus.marks_quoted" type="checkbox"> Presupuesto generado</label><label class="check"><input v-model="newStatus.marks_awaiting_quote_approval" type="checkbox"> Espera aprobación</label><label class="check"><input v-model="newStatus.marks_repair" type="checkbox"> En reparación</label><label class="check"><input v-model="newStatus.marks_completed" type="checkbox"> Finaliza trabajo</label><label class="check"><input v-model="newStatus.marks_delivered" type="checkbox"> Entrega equipo</label></div><div class="flex flex--between" style="margin-top:20px"><button class="btn btn--ghost" @click="showNew=false">Cancelar</button><button class="btn btn--primary" :disabled="!newStatus.name.trim()" @click="create">Crear estado</button></div></div></div></template>
<style scoped>.heading{align-items:flex-start;gap:16px}.heading h2{margin:0 0 6px}.status-admin{display:flex;flex-direction:column;margin-top:18px}/* Flex con wrap: con once checks por estado, una grilla de columnas fijas se desborda del card y deja el campo de asunto del email fuera de la pantalla. */.row{display:flex;flex-wrap:wrap;gap:10px 12px;align-items:end;margin:6px 0;padding:12px;border:1px solid;border-left:4px solid var(--status-color);border-radius:12px}.color{width:52px;height:40px;padding:2px;border-radius:9px;cursor:pointer;flex:none}.name{flex:1 1 200px;min-width:0}.order{flex:0 0 80px}.name,.order{margin:0}.check{display:flex;align-items:center;gap:6px;min-height:40px;white-space:nowrap;font-size:13px}.notif-config{width:100%;display:flex;flex-wrap:wrap;gap:10px 12px;align-items:end;margin-top:4px;padding-top:12px;border-top:1px dashed var(--border,#263a57)}.notif-template{flex:1 1 260px;min-width:0;margin:0}.notif-template textarea{resize:vertical;min-height:48px}.notif-hint{width:100%;margin:0;font-size:11px;color:var(--text-muted,#8290a5);word-break:break-word}.note{margin:16px 0 0}.modal-backdrop{position:fixed;inset:0;z-index:140;background:rgba(2,6,23,.72);display:grid;place-items:center;padding:20px}.status-modal{width:min(620px,100%)}.flags{display:flex;gap:18px;flex-wrap:wrap;margin-top:12px}@media(max-width:600px){.check{white-space:normal;min-height:44px}.heading{padding-bottom:2px}.status-modal{max-height:92dvh;overflow:auto}.flags{display:grid;grid-template-columns:1fr}.flags .check{padding:8px 0}}</style>